// Normalize the incoming lead row. Never invents realistic-looking
// fake data (no "John Doe", no "Acme Corp", no example.com fallbacks).
// Missing fields are reported as missing, not guessed.

function normalizeUrl(raw) {
  if (!raw || typeof raw !== 'string') return { url: '', valid: false };
  let u = raw.trim();
  if (!u) return { url: '', valid: false };
  if (!/^https?:\/\//i.test(u)) u = 'https://' + u;
  u = u.replace(/\/+$/, '');
  try {
    // Will throw on a genuinely malformed URL
    new URL(u);
    return { url: u, valid: true };
  } catch (e) {
    return { url: u, valid: false };
  }
}

const trigger = $input.item.json || {};

const name = (trigger.Name || '').toString().trim();
const email = (trigger.Email || '').toString().trim().toLowerCase();
const company = (trigger.Company || '').toString().trim();
const linkedinUrlRaw = (trigger.LinkedIn_URL || '').toString().trim();

const companyUrlResult = normalizeUrl(trigger.Company_URL);
const linkedinUrlResult = linkedinUrlRaw ? normalizeUrl(linkedinUrlRaw) : { url: '', valid: false };

return {
  json: {
    row_number: trigger.row_number ?? null,
    Name: name,
    Email: email,
    Company: company,
    Company_URL: companyUrlResult.valid ? companyUrlResult.url : '',
    LinkedIn_URL: linkedinUrlResult.valid ? linkedinUrlResult.url : '',
    missing_email: !email,
    missing_company_url: !companyUrlResult.valid,
    missing_company_name: !company,
    company_url_raw_invalid: Boolean(trigger.Company_URL) && !companyUrlResult.valid,
  }
};

// Local, offline email FORMAT validation.
// This checks only that the address is syntactically well-formed.
// It does NOT verify that the mailbox exists, is deliverable, or is
// not disposable - it is a format check, not a mailbox check.
// No API key, token, credential, or external service is used or required.

const item = $input.item.json || {};
const email = (item.Email || '').toString().trim();

// Pragmatic RFC5322-style pattern (non-backtracking, bounded label
// lengths) - good enough to catch malformed addresses without
// claiming to prove deliverability.
const EMAIL_REGEX = /^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)+$/;

let status = 'invalid';
let reason = 'empty_email';

if (email) {
  if (email.length > 254) {
    status = 'invalid';
    reason = 'exceeds_max_length';
  } else if (!EMAIL_REGEX.test(email)) {
    status = 'invalid';
    reason = 'format_does_not_match_pattern';
  } else {
    status = 'valid';
    reason = 'format_valid';
  }
}

return {
  json: {
    ...item,
    status,
    reason,
    source: 'local_format_check',
  }
};

// Classify the local email-format validation result. A missing or
// unrecognized result is NEVER treated as "valid" - it is routed to
// manual review instead. No external API is used here.

const lead = $('Normalize Lead Input').item.json;
const resp = $input.item.json || {};

let status = 'unknown';
let manualReview = true;
let source = 'Local_Format_Check';

const raw = (resp.status || '').toString().toLowerCase();
if (raw === 'valid') { status = 'valid'; manualReview = false; }
else if (raw === 'invalid') { status = 'invalid'; manualReview = false; }
else { status = 'unknown'; manualReview = true; }

return {
  json: {
    ...lead,
    email_validation_status: status,
    email_validation_source: source,
    email_validation_manual_review: manualReview,
    email_validation_raw: {
      reason: resp.reason || null,
    },
  }
};

function stripHtml(html, limit) {
  if (!html) return '';
  if (typeof html !== 'string') {
    try { html = JSON.stringify(html); } catch (e) { return ''; }
  }
  let text = html
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, ' ')
    .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<nav\b[^<]*(?:(?!<\/nav>)<[^<]*)*<\/nav>/gi, ' ')
    .replace(/<footer\b[^<]*(?:(?!<\/footer>)<[^<]*)*<\/footer>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/\s+/g, ' ')
    .trim();
  return limit ? text.slice(0, limit) : text;
}

// Try a small set of realistic About-page URL variants. Stop at the
// first one that returns real HTML content. No fabricated content.

const lead = $('Normalize Lead Input').item.json;
const base = lead.Company_URL;

const result = { available: false, url: '', content: '', source: 'about', reason: 'company_url_missing' };

if (!base) {
  return { json: { ...lead, about: result } };
}

const candidates = ['/about', '/about-us', '/company', '/who-we-are'];

for (const path of candidates) {
  const url = base + path;
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url,
      timeout: 8000,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      headers: { 'User-Agent': 'Mozilla/5.0' },
    });
    const status = res.statusCode;
    const body = typeof res.body === 'string' ? res.body : '';
    const isHtml = /<html/i.test(body) || /<body/i.test(body) || /<p[\s>]/i.test(body);
    if (status >= 200 && status < 300 && body && isHtml) {
      result.available = true;
      result.url = url;
      result.content = stripHtml(body, 2500);
      result.reason = '';
      break;
    }
  } catch (err) {
    // try next candidate
    continue;
  }
}

if (!result.available) {
  result.reason = 'page_not_found';
}

return { json: { ...lead, about: result } };

function stripHtml(html, limit) {
  if (!html) return '';
  if (typeof html !== 'string') {
    try { html = JSON.stringify(html); } catch (e) { return ''; }
  }
  let text = html
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, ' ')
    .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<nav\b[^<]*(?:(?!<\/nav>)<[^<]*)*<\/nav>/gi, ' ')
    .replace(/<footer\b[^<]*(?:(?!<\/footer>)<[^<]*)*<\/footer>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/\s+/g, ' ')
    .trim();
  return limit ? text.slice(0, limit) : text;
}

// Same pattern as About Page Research, for blog/news/content pages.

const lead = $('Normalize Lead Input').item.json;
const base = lead.Company_URL;

const result = { available: false, url: '', content: '', source: 'blog', reason: 'company_url_missing' };

if (!base) {
  return { json: { ...$input.item.json, blog: result } };
}

const candidates = ['/blog', '/news', '/insights', '/resources', '/articles'];

for (const path of candidates) {
  const url = base + path;
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url,
      timeout: 8000,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      headers: { 'User-Agent': 'Mozilla/5.0' },
    });
    const status = res.statusCode;
    const body = typeof res.body === 'string' ? res.body : '';
    const isHtml = /<html/i.test(body) || /<body/i.test(body) || /<p[\s>]/i.test(body);
    if (status >= 200 && status < 300 && body && isHtml) {
      result.available = true;
      result.url = url;
      result.content = stripHtml(body, 2500);
      result.reason = '';
      break;
    }
  } catch (err) {
    continue;
  }
}

if (!result.available) {
  result.reason = 'page_not_found';
}

return { json: { ...$input.item.json, blog: result } };

function stripHtml(html, limit) {
  if (!html) return '';
  if (typeof html !== 'string') {
    try { html = JSON.stringify(html); } catch (e) { return ''; }
  }
  let text = html
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, ' ')
    .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<nav\b[^<]*(?:(?!<\/nav>)<[^<]*)*<\/nav>/gi, ' ')
    .replace(/<footer\b[^<]*(?:(?!<\/footer>)<[^<]*)*<\/footer>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/\s+/g, ' ')
    .trim();
  return limit ? text.slice(0, limit) : text;
}

// This workflow has no authenticated LinkedIn data provider. We only
// attempt a best-effort public fetch of the URL the lead provided. If it
// cannot be fetched (which is normal - LinkedIn blocks most automated
// requests), LinkedIn data is marked unavailable. We NEVER fabricate a
// job title, employee count, industry, location, or LinkedIn posts.

const lead = $input.item.json;
const url = lead.LinkedIn_URL;

const result = { available: false, source: 'linkedin', url: url || '', content: '', reason: 'not_available' };

if (!url) {
  result.reason = 'no_linkedin_url_provided';
  return { json: { ...lead, linkedin: result } };
}

try {
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url,
    timeout: 8000,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    headers: { 'User-Agent': 'Mozilla/5.0' },
  });
  const status = res.statusCode;
  const body = typeof res.body === 'string' ? res.body : '';
  if (status >= 200 && status < 300 && body && /<html/i.test(body)) {
    result.available = true;
    result.content = stripHtml(body, 1500);
    result.reason = '';
  } else {
    result.reason = `fetch_blocked_status_${status}`;
  }
} catch (err) {
  result.reason = 'fetch_failed';
}

return { json: { ...lead, linkedin: result } };

// Best-effort technology detection from publicly visible homepage HTML
// evidence only (script tags, meta generators, known CDN/asset paths).
// We explicitly distinguish confirmed vs inferred vs unknown and never
// overclaim a "confirmed technology stack" without real evidence.

const lead = $input.item.json;
let homepageHtml = '';
try {
  const homepageItem = $('Homepage Research').item;
  homepageHtml = (homepageItem && typeof homepageItem.json.data === 'string') ? homepageItem.json.data : '';
} catch (e) {
  homepageHtml = '';
}

const indicators = [
  { name: 'WordPress', pattern: /wp-content|wp-includes|\/wp-json\//i, confidence: 'confirmed' },
  { name: 'Shopify', pattern: /cdn\.shopify\.com|shopify-analytics/i, confidence: 'confirmed' },
  { name: 'Webflow', pattern: /webflow\.com|wf-page/i, confidence: 'confirmed' },
  { name: 'Squarespace', pattern: /squarespace\.com|static1\.squarespace/i, confidence: 'confirmed' },
  { name: 'HubSpot', pattern: /js\.hs-scripts\.com|hubspot\.com\/forms/i, confidence: 'confirmed' },
  { name: 'Google Analytics', pattern: /googletagmanager\.com|google-analytics\.com\/analytics\.js|gtag\(/i, confidence: 'confirmed' },
  { name: 'Stripe (payments)', pattern: /js\.stripe\.com/i, confidence: 'confirmed' },
  { name: 'Cloudflare', pattern: /cloudflare\.com|cf-ray/i, confidence: 'inferred' },
  { name: 'React', pattern: /data-reactroot|__next|_next\/static/i, confidence: 'inferred' },
  { name: 'Intercom', pattern: /widget\.intercom\.io/i, confidence: 'confirmed' },
];

const found = [];
if (homepageHtml) {
  for (const ind of indicators) {
    if (ind.pattern.test(homepageHtml)) {
      found.push({ technology: ind.name, confidence: ind.confidence });
    }
  }
}

const result = {
  technographics: found,
  confidence: found.length ? (found.some(f => f.confidence === 'confirmed') ? 'evidence_based' : 'inferred_only') : 'unknown',
  source: 'homepage_html_scan',
};

return { json: { ...lead, technographics: result } };

// Build one clean, structured payload for the AI. Never overwrite real
// lead fields with fake defaults. Every research source keeps its own
// available/url/content/source/reason shape so the AI (and any human
// reviewer) can see exactly what was and wasn't found.

const lead = $input.item.json;
const validation = $('Normalize Validation Result').item.json;

const homepageRaw = (() => {
  try {
    const item = $('Homepage Research').item;
    return item && typeof item.json.data === 'string' ? item.json.data : '';
  } catch (e) { return ''; }
})();

function stripHtml(html, limit) {
  if (!html || typeof html !== 'string') return '';
  const text = html
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, ' ')
    .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  return limit ? text.slice(0, limit) : text;
}

const homepage = {
  available: Boolean(homepageRaw),
  url: lead.Company_URL || '',
  content: stripHtml(homepageRaw, 2500),
  source: 'homepage',
  reason: homepageRaw ? '' : (lead.Company_URL ? 'fetch_failed' : 'company_url_missing'),
};

const about = lead.about || { available: false, url: '', content: '', source: 'about', reason: 'not_run' };
const blog = lead.blog || { available: false, url: '', content: '', source: 'blog', reason: 'not_run' };
const linkedin = lead.linkedin || { available: false, url: lead.LinkedIn_URL || '', content: '', source: 'linkedin', reason: 'not_run' };
const technographics = lead.technographics || { technographics: [], confidence: 'unknown', source: 'homepage_html_scan' };

const errors = [];
if (!homepage.available) errors.push({ source: 'homepage', reason: homepage.reason });
if (!about.available) errors.push({ source: 'about', reason: about.reason });
if (!blog.available) errors.push({ source: 'blog', reason: blog.reason });
if (!linkedin.available) errors.push({ source: 'linkedin', reason: linkedin.reason });

const sourcesAvailable = [homepage.available, about.available, blog.available].filter(Boolean).length;
let researchStatus = 'no_sources_available';
if (sourcesAvailable === 3) researchStatus = 'full_research';
else if (sourcesAvailable > 0) researchStatus = 'partial_research';
else researchStatus = lead.Company_URL ? 'research_failed' : 'company_url_missing';

return {
  json: {
    lead: {
      name: lead.Name || '',
      email: lead.Email || '',
      company: lead.Company || '',
      company_url: lead.Company_URL || '',
      linkedin_url: lead.LinkedIn_URL || '',
    },
    email_validation: {
      status: validation.email_validation_status,
      source: validation.email_validation_source,
      manual_review: validation.email_validation_manual_review,
    },
    research: { homepage, about, blog, linkedin, technographics },
    research_status: researchStatus,
    errors,
    // Flat fields kept for convenience in downstream nodes/expressions
    Name: lead.Name || '',
    Email: lead.Email || '',
    Company: lead.Company || '',
    Company_URL: lead.Company_URL || '',
    LinkedIn_URL: lead.LinkedIn_URL || '',
  }
};

