// Robustly parse the AI's JSON output. Never crash the workflow and
// never fabricate email content when parsing fails.

let rawText = '';
const CONFIDENCE_THRESHOLD = 80;

try {
  const inputData = $input.item?.json;
  rawText = inputData?.text
    || inputData?.content?.parts?.[0]?.text
    || inputData?.message?.content
    || (typeof inputData === 'string' ? inputData : '');

  if (!rawText) throw new Error('No output text received from AI node.');

  let sanitized = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();
  const match = sanitized.match(/\{[\s\S]*\}/);
  if (match) sanitized = match[0];

  const parsed = JSON.parse(sanitized);

  const subjectOptions = Array.isArray(parsed.email_subject_options) ? parsed.email_subject_options.filter(Boolean) : [];
  let selectedSubject = (parsed.selected_subject || '').toString().trim();
  if (subjectOptions.length && !subjectOptions.includes(selectedSubject)) {
    selectedSubject = subjectOptions[0];
  }

  const score = Number.isFinite(Number(parsed.data_confidence_score)) ? Math.max(0, Math.min(100, Number(parsed.data_confidence_score))) : 0;
  const emailBody = (parsed.email_body || '').toString().trim();

  const requiresHuman = Boolean(parsed.requires_human_flag) || !emailBody || !selectedSubject || score < CONFIDENCE_THRESHOLD;

  return {
    json: {
      parse_status: 'success',
      status: parsed.status || 'success',
      data_confidence_score: score,
      strategy_used: score >= CONFIDENCE_THRESHOLD ? 'Hyper-Personalized' : 'Value-First B2B Outreach Strategy',
      company_summary: parsed.company_summary || '',
      target_audience: parsed.target_audience || '',
      identified_pain_point: parsed.identified_pain_point || '',
      evidence_used: Array.isArray(parsed.evidence_used) ? parsed.evidence_used : [],
      email_subject_options: subjectOptions,
      selected_subject: selectedSubject,
      email_body: emailBody,
      requires_human_flag: requiresHuman,
    }
  };
} catch (error) {
  return {
    json: {
      parse_status: 'failed',
      status: 'parsing_error',
      data_confidence_score: 0,
      strategy_used: 'Value-First B2B Outreach Strategy',
      company_summary: '',
      target_audience: '',
      identified_pain_point: '',
      evidence_used: [],
      email_subject_options: [],
      selected_subject: '',
      email_body: '',
      requires_human_flag: true,
      error_message: error.message,
      raw_output: rawText,
    }
  };
}

// Generate a short-lived, single-use approval token. Tokens expire after
// 24 hours and old/expired tokens are cleaned up on every run so the
// static data store doesn't grow forever.

function simpleHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = (hash << 5) - hash + str.charCodeAt(i);
    hash |= 0;
  }
  return Math.abs(hash).toString(36);
}

const TOKEN_TTL_MS = 24 * 60 * 60 * 1000; // 24 hours - adjust if needed

const staticData = $getWorkflowStaticData('global');
if (!staticData.approvalTokens) staticData.approvalTokens = {};

// Clean up expired tokens
const now = Date.now();
for (const [tok, rec] of Object.entries(staticData.approvalTokens)) {
  if (rec && rec.expiresAt && rec.expiresAt < now) {
    delete staticData.approvalTokens[tok];
  }
}

const results = [];
for (const item of $input.all()) {
  const email = (item.json.Email || '').toString().trim().toLowerCase();
  const token = simpleHash(email + now + Math.random()).slice(0, 12);

  staticData.approvalTokens[token] = {
    email,
    createdAt: now,
    expiresAt: now + TOKEN_TTL_MS,
    used: false,
    action: null,
    claimed: false,
    claimedAt: null,
  };

  results.push({ json: { ...item.json, approvalToken: token } });
}

return results;

