// Resolve a Telegram callback into an action + email, honoring
// expiration and duplicate-click protection. A token can only ever be
// used once. To also protect against duplicate/concurrent deliveries of
// the SAME callback (e.g. a Telegram redelivery, or two near-simultaneous
// taps), the token is atomically "claimed" right here - before any
// Google Sheets lookup or send attempt happens. A claim is short-lived:
// if the run that claimed it never finishes (crash, blocked, etc.), the
// claim goes stale after CLAIM_TTL_MS and a fresh click can claim it
// again. A token that reaches `used: true` is permanently consumed
// regardless of claim state - that only happens after the requested
// action actually completes (see Mark Token Used).

const CLAIM_TTL_MS = 2 * 60 * 1000; // 2 minutes

const staticData = $getWorkflowStaticData('global');
const tokens = staticData.approvalTokens || {};

const results = [];
for (const item of $input.all()) {
  let raw = '';
  if (item.json.callback_query && item.json.callback_query.data) {
    raw = item.json.callback_query.data;
  }

  const parts = raw.split(':');
  const action = (parts[0] || '').trim().toLowerCase();
  const token = (parts[1] || '').trim();

  const record = tokens[token];
  const now = Date.now();

  const tokenExists = Boolean(record);
  const tokenExpired = tokenExists ? (record.expiresAt < now) : false;
  const alreadyUsed = tokenExists ? Boolean(record.used) : false;
  const claimStale = tokenExists && record.claimed && record.claimedAt
    ? (now - record.claimedAt > CLAIM_TTL_MS)
    : true;
  const alreadyClaimed = tokenExists ? Boolean(record.claimed) && !claimStale : false;
  const resolvedEmail = tokenExists ? record.email : '';

  const tokenValid = tokenExists && !tokenExpired && !alreadyUsed && !alreadyClaimed;

  if (tokenValid) {
    // Claim it now, in this same pass, so a duplicate delivery of this
    // callback that arrives moments later sees alreadyClaimed = true.
    record.claimed = true;
    record.claimedAt = now;
  }

  results.push({
    json: {
      ...item.json,
      approvalAction: action,
      approvalToken: token,
      leadEmail: resolvedEmail,
      tokenExists,
      tokenExpired,
      tokenAlreadyUsed: alreadyUsed,
      tokenAlreadyClaimed: alreadyClaimed,
      tokenValid,
    }
  });
}

return results;

