// Normalize a filtered Google Sheets read into exactly one found/not-found
// result PER UPSTREAM ITEM, using n8n's pairedItem tracking. This stays
// correct even when this execution is processing more than one lead/event
// at once (e.g. several unread emails in one Gmail poll): a match for one
// item can never be mistaken for a match belonging to another item.
//
// IMPORTANT (reliability fix): the upstream Google Sheets "read" node runs
// with onError: continueRegularOutput, so a Sheets API failure (auth error,
// rate limit, timeout, etc.) does NOT stop the workflow - instead it comes
// through this node's input as a normal item shaped like { json: { error: ... } }.
// That error item must NEVER be mistaken for a matched lead row - doing so
// would let missing/undefined fields (Email, Status, etc.) silently flow
// forward as if they were real data. We explicitly detect and separate out
// error items below and always resolve them to leadFound: false, with the
// underlying error message preserved for the alert / manual-review path.
//
// Matched rows carry their pairedItem metadata forward so that downstream
// nodes can still resolve $('Resolve Approval Token').item correctly. Not-found
// results have no corresponding sheet row to inherit pairedItem from, but
// nothing downstream needs ancestor lookups on that path.

const upstreamItems = $('Resolve Approval Token').all();
const matchedRows = $input.all();

const matchByIndex = {};
const lookupErrorByIndex = {};
for (const row of matchedRows) {
  const idx = (row.pairedItem && typeof row.pairedItem.item === 'number')
    ? row.pairedItem.item
    : (row.pairedItem && Array.isArray(row.pairedItem) && typeof row.pairedItem[0]?.item === 'number')
      ? row.pairedItem[0].item
      : 0;

  const isErrorItem = Boolean(row.json) && Object.prototype.hasOwnProperty.call(row.json, 'error');
  if (isErrorItem) {
    // A Sheets API failure - never treat this as a found/matched lead row.
    if (!(idx in lookupErrorByIndex)) {
      const errVal = row.json.error;
      lookupErrorByIndex[idx] = (errVal && errVal.message) ? errVal.message : (typeof errVal === 'string' ? errVal : 'Google Sheets lookup failed');
    }
    continue;
  }

  // If a later row also maps to the same index (shouldn't happen with
  // returnAllMatches: false, but be defensive), keep the first match.
  if (!(idx in matchByIndex)) matchByIndex[idx] = row;
}

const results = [];
for (let i = 0; i < upstreamItems.length; i++) {
  const upstream = upstreamItems[i].json;
  const searchedEmail = upstream.leadEmail || '';
  const matchedRow = matchByIndex[i];
  if (matchedRow) {
    const out = { json: { ...matchedRow.json, leadFound: true } };
    if (matchedRow.pairedItem !== undefined) out.pairedItem = matchedRow.pairedItem;
    results.push(out);
  } else {
    const lookupError = lookupErrorByIndex[i];
    results.push({
      json: {
        leadFound: false,
        lookupFailed: Boolean(lookupError),
        reason: lookupError
          ? ('Google Sheets lookup failed: ' + lookupError)
          : ('No sheet row found for email: ' + searchedEmail),
        approvalToken: upstream.approvalToken || '',
        searchedEmail,
      }
    });
  }
}

return results;

