  const m = j.headers.from.match(/<([^>]+)>/);
  senderEmail = m ? m[1] : j.headers.from.trim();
}

senderEmail = (senderEmail || '').toString().trim().toLowerCase();

return {
  json: {
    ...j,
    senderEmail,
    senderIdentified: Boolean(senderEmail),
